'use strict';

const {parse}=require('../src/ast');

/** @typedef {{name:string,param:string,expression:string,instructions:number,bytes:number[]}} RecoveredProgram */

/**
 * An intentionally seedless, source-only adversary against the experimental
 * register VM generated by src/register-vm.js. The attacker does not import
 * the compiler or receive the seed, input JavaScript or original function.
 *
 * It reads the distributed wrapper, interpreter switch, opcode rotation,
 * immediate mask and bytecode array, then reconstructs a native JS formula.
 * Supported only for this particular public VM emitter's syntax.
 *
 * @param {string} output
 * @returns {RecoveredProgram}
 */
function recoverRegisterVm(output) {
  // All extracted fragments are from the public obfuscated source alone.
  const wrapper=/function\s+([A-Za-z_$][\w$]*)\s*\(\s*([A-Za-z_$][\w$]*)\s*\)\s*\{\s*return\s+\(\s*(_rvm_[0-9a-f]+)\(\s*\2\s*\)\s*\)\s*;\s*\}/u.exec(output);
  if(!wrapper)throw new TypeError('Unsupported register VM wrapper');
  const [,name,param,helper]=wrapper;
  const escape=/** @param {string} value @returns {string} */ value=>
    value.replace(/[.*+?^${}()|[\]\\]/gu,'\\$&');
  const helperRe=escape(helper);
  const cache=new RegExp(helperRe+'Cache=\\[(\\d+(?:,\\d+)*)\\]','u').exec(output);
  if(!cache)throw new TypeError('Missing published VM bytecode');
  const bytes=cache[1].split(',').map(Number);
  const rotate=/switch\s*\(\s*\(bytes\[pc\+\+\]-(\d+)\)&255\s*\)/u.exec(output);
  if(!rotate)throw new TypeError('Missing published opcode rotation');
  const rotation=Number(rotate[1]);
  /** @type {Map<number,{operator:string,key:number}>} */
  const opcodes=new Map();
  const patterns=/case\s+(\d+):value(>>>|>>|<<|\+|-|\*|\^|&|\|)=\(bytes\[pc\+\+\]\^(\d+)\);break;/gu;
  for(const match of output.matchAll(patterns)) {
    const code=Number(match[1]),operator=match[2],key=Number(match[3]);
    if(opcodes.has(code))throw new TypeError('Duplicate opcode');
    opcodes.set(code,{operator,key});
  }
  if(!opcodes.size)throw new TypeError('Missing public instruction semantics');
  let expression=param;
  let index=0;
  let instructions=0;
  while(index<bytes.length) {
    const op=(bytes[index++]-rotation)&255;
    if(op===255) {
      if(index!==bytes.length)throw new TypeError('Trailing VM bytes');
      parse('function reconstructed('+param+'){return '+expression+';}', 'script');
      return {name,param,expression,instructions,bytes};
    }
    if(index>=bytes.length)throw new TypeError('Missing operand byte');
    const descriptor=opcodes.get(op);
    if(!descriptor)throw new TypeError('Unknown instruction '+op);
    const operand=bytes[index++]^descriptor.key;
    expression='('+expression+descriptor.operator+operand+')';
    instructions++;
  }
  throw new TypeError('Missing VM termination');
}

module.exports={recoverRegisterVm};
